// 诊断：分区恢复后，高任期的少数派节点能不能赢得选举？
func TestHighTermRejoin(t *testing.T) {
	for _, leaderInMinority := range []bool{false, true} {
		net := NewNetwork(5, 20, 10, 0, 7)
		c := New(5, net, 400, 300, 7)
		for i := int64(0); i < 300; i++ {
			c.Step(5)
		}
		l := c.Leader()
		if l == nil {
			t.Fatal("no leader")
		}
		// 提交一批日志
		for i := 0; i < 30; i++ {
			c.Submit(fmt.Sprintf("pre%d", i))
			for k := 0; k < 6; k++ {
				c.Step(5)
			}
		}
		for k := 0; k < 400; k++ {
			c.Step(5)
		}
		committedBefore := c.MaxCommit()

		// 构造分区：让 leader 落在多数派或少数派
		grp := make([]int, 5)
		var minority []int
		if leaderInMinority {
			// leader + 一个邻居 = 少数派
			for i := range grp {
				grp[i] = 0
			}
			grp[l.id] = 1
			other := (l.id + 1) % 5
			grp[other] = 1
			minority = []int{l.id, other}
		} else {
			for i := range grp {
				grp[i] = 0
			}
			cnt := 0
			for i := 0; i < 5 && cnt < 2; i++ {
				if i != l.id {
					grp[i] = 1
					minority = append(minority, i)
					cnt++
				}
			}
		}
		net.Partition(grp)

		// 分区期间：多数派继续写入；少数派任期疯涨
		for i := 0; i < 60; i++ {
			c.Submit(fmt.Sprintf("during%d", i))
			for k := 0; k < 10; k++ {
				c.Step(5)
			}
		}
		for k := 0; k < 3000; k++ {
			c.Step(5)
		}
		minTerms := []int{}
		for _, i := range minority {
			minTerms = append(minTerms, c.nodes[i].term)
		}
		majLeader := c.Leader()
		majTerm, majCommit := 0, c.MaxCommit()
		if majLeader != nil {
			majTerm = majLeader.term
		}
		fmt.Printf("\n=== leaderInMinority=%v ===\n", leaderInMinority)
		fmt.Printf("分区期间：少数派 %v 的 term=%v ｜ 多数派 leader=%v term=%d ｜ 已提交=%d\n",
			plus1(minority), minTerms, nameOf(majLeader), majTerm, majCommit)
		for _, i := range minority {
			n := c.nodes[i]
			fmt.Printf("  少数派 N%d: state=%v term=%d lastLog=(term=%d,idx=%d) commit=%d\n",
				i+1, n.state, n.term, n.last().Term, n.last().Index, n.commitIndex)
		}

		// 恢复
		net.Heal()
		for k := 0; k < 4000; k++ {
			c.Step(5)
		}
		after := c.Leader()
		fmt.Printf("恢复后：leader=%v term=%d ｜ 最高已提交=%d（分区前 %d）\n",
			nameOf(after), termOf(after), c.MaxCommit(), committedBefore)
		fmt.Printf("  恢复后的 leader 来自：%s\n", side(after, grp, minority))
		fmt.Printf("  安全性违反：%d 条 %v\n", len(c.Violations), c.Violations)
		// 校验：分区前已提交的日志是否都还在
		lost := 0
		for idx, e := range c.globalCommitted {
			if idx <= committedBefore {
				for _, n := range c.nodes {
					if got, ok := n.at(idx); ok && (got.Term != e.Term || got.Cmd != e.Cmd) {
						lost++
					}
				}
			}
		}
		fmt.Printf("  分区前已提交日志被改动的副本数：%d\n", lost)
	}
}

func plus1(a []int) []int { o := make([]int, len(a)); for i, x := range a { o[i] = x + 1 }; return o }
func nameOf(n *Node) string { if n == nil { return "无" }; return fmt.Sprintf("N%d", n.id+1) }
func termOf(n *Node) int { if n == nil { return -1 }; return n.term }
func side(n *Node, grp []int, minority []int) string {
	if n == nil { return "—" }
	for _, m := range minority { if m == n.id { return "★ 少数派（旧日志）" } }
	return "多数派（新日志）"
}
